import{_ as s,o as t,c as i,a5 as e}from"./chunks/framework.CXroN2RO.js";const g=JSON.parse('{"title":"所有権と借用","description":"","frontmatter":{"title":"所有権と借用","study":{"source":"C++ Wiki","kind":"本文","status":"既存原稿","summary":"所有権 (ownership): 「このオブジェクトを破棄する責任を誰が持つか」。C++設計の背骨で、スマートポインタは所有権を型で表す道具 借用 (borrowing): 所有せず「一時的に使わせてもらう」こと(参照・非所有ポインタ)。借用は所有者より長生きしてはいけない——この規律を、C++では"}},"headers":[],"relativePath":"runtime/memory/ownership-and-borrowing.md","filePath":"runtime/memory/ownership-and-borrowing.md"}'),n={name:"runtime/memory/ownership-and-borrowing.md"};function r(l,a,o,p,d,h){return t(),i("div",null,[...a[0]||(a[0]=[e(`<h1 id="所有権と借用" tabindex="-1">所有権と借用 <a class="header-anchor" href="#所有権と借用" aria-label="Permalink to &quot;所有権と借用&quot;">​</a></h1><h2 id="一言で言うと" tabindex="-1">一言で言うと <a class="header-anchor" href="#一言で言うと" aria-label="Permalink to &quot;一言で言うと&quot;">​</a></h2><ul><li><strong>所有権 (ownership)</strong>: 「このオブジェクトを<strong>破棄する責任</strong>を誰が持つか」。C++設計の背骨で、<a href="/study/languages/cpp/smart-pointers.html">スマートポインタ</a>は所有権を型で表す道具</li><li><strong>借用 (borrowing)</strong>: 所有せず「一時的に使わせてもらう」こと(参照・非所有ポインタ)。<strong>借用は所有者より長生きしてはいけない</strong>——この規律を、C++ではプログラマが(Rustでは型システムが)守る</li></ul><h2 id="なぜ「所有」という概念が必要か" tabindex="-1">なぜ「所有」という概念が必要か <a class="header-anchor" href="#なぜ「所有」という概念が必要か" aria-label="Permalink to &quot;なぜ「所有」という概念が必要か&quot;">​</a></h2><p>GCのないC++では、全オブジェクトについて「誰がいつdeleteするか」が決まっていなければ、リークか二重解放になります。これを個別に暗記するのは不可能なので、<strong>「所有者は常に1つ(または明示的に共有)」という構造</strong>をコードに刻む——それが所有権設計です。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>所有の木(良い設計は木構造になる):</span></span>
<span class="line"><span>Game</span></span>
<span class="line"><span> ├─所有→ Scene</span></span>
<span class="line"><span> │        ├─所有→ vector&lt;unique_ptr&lt;Entity&gt;&gt;</span></span>
<span class="line"><span> │        │              └─所有→ unique_ptr&lt;Weapon&gt;</span></span>
<span class="line"><span> │        └─所有→ ParticleSystem</span></span>
<span class="line"><span> └─所有→ AssetManager ─所有→ 各アセット</span></span>
<span class="line"><span>Entityが持つ「Target* (敵への参照)」は借用 ── 木を横断する矢印(所有しない)</span></span></code></pre></div><h2 id="型による表現-c-の語彙" tabindex="-1">型による表現(C++の語彙) <a class="header-anchor" href="#型による表現-c-の語彙" aria-label="Permalink to &quot;型による表現(C++の語彙)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>書き方</th><th>意味</th></tr></thead><tbody><tr><td><code>T</code> メンバ / ローカル</td><td>完全所有(寿命が自分と一体)— <strong>第一候補</strong></td></tr><tr><td><code>std::unique_ptr&lt;T&gt;</code></td><td>単独所有(ヒープ上)。ムーブ=所有権の譲渡</td></tr><tr><td><code>std::shared_ptr&lt;T&gt;</code></td><td>共有所有(最後の1人が破棄)</td></tr><tr><td><code>T&amp;</code> / <code>T*</code></td><td><strong>借用</strong>(非所有)。呼び出しの間だけ/相手が生きてる保証がある間だけ</td></tr><tr><td><code>std::weak_ptr&lt;T&gt;</code></td><td>「死んでいるかもしれない相手」への安全な借用</td></tr><tr><td>関数が <code>unique_ptr&lt;T&gt;</code> を受け取る</td><td>「所有権をよこせ」というシグネチャ</td></tr><tr><td>関数が <code>T&amp;</code>/<code>T*</code> を受け取る</td><td>「借りるだけ」というシグネチャ</td></tr></tbody></table><p><strong>関数シグネチャが所有権の契約書になる</strong>——これが規約の力です。<code>Foo(Enemy* e)</code> を見たら「借用(呼び出しの間だけ使う)」と読み、<code>Foo(std::unique_ptr&lt;Enemy&gt; e)</code> なら「あげたら戻ってこない」と読みます。</p><h2 id="借用の安全条件" tabindex="-1">借用の安全条件 <a class="header-anchor" href="#借用の安全条件" aria-label="Permalink to &quot;借用の安全条件&quot;">​</a></h2><p>借用が安全なのは「<strong>所有者の寿命 &gt; 借用の寿命</strong>」が構造的に保証されるときだけ:</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 安全な借用: 呼び出しの間だけ(所有者は呼び出し側で生きている)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Render</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Enemy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> e</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 危険な借用: 保存する借用(所有者がいつ消えるか、この型は知らない)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Turret</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Enemy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> target_ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> nullptr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // 敵が先に死んだら? → dangling</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">};</span></span></code></pre></div><p>「<strong>保存される借用</strong>」がC++設計の急所です。選択肢:</p><ol><li>所有構造上、相手が確実に長生き(親への参照など)→ 生ポインタ/参照でよい(コメントで根拠を書く)</li><li>相手が先に死にうる → <code>weak_ptr</code>(shared管理なら)/ <strong>世代付きハンドル+ID</strong>(<a href="/study/game/patterns/object-pool.html">Object Pool</a>。大量オブジェクトの定石)/ 死亡イベント購読でnullクリア</li><li>毎フレーム検索し直す(保存しない)——単純で意外と正解</li></ol><h2 id="rust-の「借用」との関係-用語の出所" tabindex="-1">Rust の「借用」との関係(用語の出所) <a class="header-anchor" href="#rust-の「借用」との関係-用語の出所" aria-label="Permalink to &quot;Rust の「借用」との関係(用語の出所)&quot;">​</a></h2><p>「借用」はRustの用語(borrow checker)として有名になりました。Rustはこのページの規律——所有者は1つ、借用は所有者より短命、可変借用は同時に1つ——を<strong>コンパイラが強制</strong>します。C++は同じ規律を<strong>慣習と型(スマートポインタ)で近似</strong>する言語です。C++プログラマがRustの概念を学ぶ価値は、「自分が暗黙に守るべき規律の明文化」が手に入ることにあります。</p><h2 id="c-との対応" tabindex="-1">C#との対応 <a class="header-anchor" href="#c-との対応" aria-label="Permalink to &quot;C#との対応&quot;">​</a></h2><ul><li>C#は「全員がshared_ptr(GC版)」の世界: 参照を持つ人が全員いなくなるまで死なない。所有権の概念が<strong>言語上は不要</strong>(だからこそ、いつメモリが返るか誰にも分からない)</li><li>ただしC#にも「論理的な所有権」は存在する: Dispose責任(usingを書くのは誰?)、イベント購読の解除責任、オブジェクトプールの返却責任——<strong>C#で曖昧にできていたものをC++は明示させる</strong>、と捉えると学びやすい</li><li>Unityの <code>Destroy(gameObject)</code> は「エンジンがGameObjectを所有し、破棄要求を受け付ける」構造。C#参照が残っていてもエンジン側の実体は消える(だからMissingReferenceが出る)——実はUnityにも所有権問題は存在していた</li></ul><h2 id="unity開発者が誤解しやすい点" tabindex="-1">Unity開発者が誤解しやすい点 <a class="header-anchor" href="#unity開発者が誤解しやすい点" aria-label="Permalink to &quot;Unity開発者が誤解しやすい点&quot;">​</a></h2><ol><li>「参照を持っていれば安全」— C++では参照は延命しない(借用)。延命するのはshared_ptrだけ</li><li>「とりあえずshared_ptrにすれば所有権を考えなくていい」— 所有者不明の設計になり、循環と「いつ消えるか不明」を招く。<strong>所有の木を書く</strong>のが先</li><li>「ポインタ引数=危険」— 借用の生ポインタは現代C++の正当な語彙(→ <a href="/study/languages/cpp/smart-pointers.html">スマートポインタ</a>)</li></ol><h2 id="ゲーム開発での使用例" tabindex="-1">ゲーム開発での使用例 <a class="header-anchor" href="#ゲーム開発での使用例" aria-label="Permalink to &quot;ゲーム開発での使用例&quot;">​</a></h2><ul><li>シーングラフ: 親が子をunique_ptrで所有、子は親を生ポインタで借用(親は必ず長生き)</li><li>ターゲット参照: ハンドル(ID+世代)方式が業界定石(大量・頻繁な生死があるため)</li><li>アセット: AssetManagerが所有、ゲームオブジェクトはハンドル/shared_ptrで参照</li><li>「このシステムを破棄する順序」= 所有と借用の依存関係の逆順(エンジンのShutdown設計)</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>所有権とは何の責任ですか。所有の構造はどんな形が理想ですか。</li><li>「保存される借用」がなぜ急所で、3つの対処は?</li><li>C#に所有権の概念が(言語上)不要な理由と、それでも残る「論理的所有」の例は?</li></ol><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><p>自分のゲーム(またはsamples/component_entity.cpp)について「所有の木」を描き、木を横断する参照(借用)をすべて列挙してください。各借用について「所有者より短命と言える根拠」または「言えない場合の対策」を書き込んでください。</p><hr><p>前: <a href="/study/runtime/memory/storage-duration-and-lifetime.html">記憶域期間とスコープ・寿命</a> | <a href="/study/runtime/memory/">カテゴリ目次</a> | 次: <a href="/study/runtime/memory/memory-bugs.html">メモリバグ図鑑</a></p>`,28)])])}const u=s(n,[["render",r]]);export{g as __pageData,u as default};
